.table-collapsibles {
    width: 100%;

    tr {
        position: relative;

        /*
          Safari doesn't support `position: relative` on `<tr>` elements,
          but these two properties can be used as an alternative.
          Source: https://mtsknn.fi/blog/relative-tr-in-safari/
        */
        transform: translate(0);
        clip-path: inset(0);
        &:focus-within {
            outline: 2px solid transparent;
            outline-offset: -2px; /* Needs to be negative because of the `clip-path` above */
        }

        &:has(td > button:only-child):hover {
            background-color: $primary-light;
        }
        &:has(button[aria-expanded="true"]) {
            background-color: $primary;
            &:hover {
                background-color: $primary !important;
            }
            th,
            td {
                color: #fff;
            }
        }
    }
    th,
    td {
        border-bottom: none;
        vertical-align: baseline;
        padding-top: 0.3rem;
        padding-bottom: 0.3rem;
    }
    th {
        font-size: var(--step--1);
        font-weight: 300;
        white-space: nowrap;
        @include tablet {
            padding-right: var(--space-3xl);
        }
    }
    td {
        > button:only-child {
            width: max-content;
            margin-top: 0.3em;
            position: static;
            // tot el row clicable
            &::after {
                content: "";
                display: block;
                position: absolute;
                width: 100%;
                height: 100%;
                left: 0;
                top: 0;
                background: none;

                // Safari fix
                inset: 0;
            }
            &[aria-expanded="true"] img {
                transform: rotate(0.125turn);
                filter: grayscale(1) brightness(100);
            }
        }
        &:last-child {
            width: 100%;
        }
        table {
            th,
            td {
                padding-top: 0.25em;
                padding-bottom: 0.25em;
            }
            th {
                padding-left: 0;
                padding-right: var(--space-xl);
                font-size: var(--step-0);
                font-weight: 600;
            }
            td {
                font-weight: normal;
            }
        }

        // Desplegable
        &[colspan] {
            font-weight: normal;
        }
    }
}
