.main-header {
    background-color: rgba(255, 255, 255, 0.75);
    padding-top: var(--space-s-l);
    padding-bottom: var(--space-m);
    position: sticky;
    top: 0;
    z-index: 10000;
    backdrop-filter: blur(20px);
    &:not(:has(+ main > .has-background-grey-light:first-child)) {
        margin-bottom: var(--space-m);
    }
    &:has(+ main > .has-background-black:first-child),
    .home & {
        margin-bottom: 0 !important;
    }
    > div {
        @include mobile {
            .lang {
                order: -1;
            }
        }
        @include tablet {
            .lang {
                order: 3;
            }
            .header-search {
                order: 2;
                margin-left: auto;
                margin-right: 1.5rem;
            }
            .navigation {
                order: 4;
            }
        }
        @include fullhd {
            .lang {
                order: 4;
                padding-bottom: var(--space-m);
            }
            .header-search {
                order: 3;
                margin-left: 0;
                padding-bottom: var(--space-m);
            }
            .navigation {
                order: 2;
                height: auto;
                margin-left: auto;
                margin-right: var(--space-m);
            }
        }
    }
    @include fullhd {
        // padding-bottom: var(--space-xs);
        padding-bottom: 0;
        // transition: background-color 0.3s ease-in-out;
        // .home:not(.slider-out) & {
        //     background-color: rgba(0, 0, 0, 0.5);
        //     position: fixed;
        //     z-index: 10;
        //     width: 100%;
        //     // backdrop-filter: none;
        // }
    }
    .wrapper {
        align-items: center;
        @include fullhd {
            align-items: flex-end;
        }
    }
}
